class Solution {
    public int deleteGreatestValue(int[][] grid){
        for(int[] row:grid)Arrays.sort(row);
        int answer=0;
        for(int col=0;col<grid[0].length;col++){
            int maximum=0;
            for(int[] row:grid)maximum=Math.max(maximum,row[col]);
            answer+=maximum;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun deleteGreatestValue(grid:Array<IntArray>):Int{
        for(row in grid)row.sort();
        var answer=0;
        for(col in grid[0].indices){
            var maximum=0;
            for(row in grid)maximum=maxOf(maximum,row[col]);
            answer+=maximum
        };
        return answer
    }
}

